import socket, concurrent.futures as cf
def scan(args):
    ip, port = args
    s = socket.socket(); s.settimeout(0.4)
    try:
        s.connect((ip, port)); return (ip, port)
    except Exception:
        return None
    finally:
        s.close()
targets = [(ip, p) for ip in ("192.168.160.1","192.168.160.2") for p in range(1, 10001)]
hits = []
with cf.ThreadPoolExecutor(max_workers=400) as ex:
    for r in ex.map(scan, targets):
        if r: hits.append(r)
print("open ports:", hits)
EOF"}

